class Solution {
public:
    string findShortestWay(vector<vector<int>>& maze, vector<int>& ball, vector<int>& hole) {
        int m = maze.size(), n = maze[0].size();
        const int dr[4] = {1, 0, 0, -1};
        const int dc[4] = {0, -1, 1, 0};
        const string dirs = "dlru";
        using State = tuple<int, string, int, int>;
        priority_queue<State, vector<State>, greater<State>> pq;
        vector<vector<int>> dist(m, vector<int>(n, INT_MAX));
        vector<vector<string>> path(m, vector<string>(n, "~"));
        dist[ball[0]][ball[1]] = 0;
        path[ball[0]][ball[1]] = "";
        pq.push(make_tuple(0, "", ball[0], ball[1]));
        while (!pq.empty()) {
            int steps, r, c;
            string route;
            tie(steps, route, r, c) = pq.top();
            pq.pop();
            if (steps != dist[r][c] || route != path[r][c]) {
                continue;
            }
            if (r == hole[0] && c == hole[1]) {
                return route;
            }
            for (int d = 0; d < 4; ++d) {
                int nr = r, nc = c, count = 0;
                while (nr + dr[d] >= 0 && nr + dr[d] < m &&
                       nc + dc[d] >= 0 && nc + dc[d] < n &&
                       maze[nr + dr[d]][nc + dc[d]] == 0) {
                    nr += dr[d];
                    nc += dc[d];
                    ++count;
                    if (nr == hole[0] && nc == hole[1]) {
                        break;
                    }
                }
                int nd = steps + count;
                string np = route + dirs[d];
                if (nd < dist[nr][nc] || (nd == dist[nr][nc] && np < path[nr][nc])) {
                    dist[nr][nc] = nd;
                    path[nr][nc] = np;
                    pq.push(make_tuple(nd, np, nr, nc));
                }
            }
        }
        return "impossible";
    }
};
